args.command:
cd /tmp/probe/alias && rm -rf cases/c_regex
mkcase() { d=$1; mkdir -p "cases/$d"; cat > "cases/$d/$d.go"; }
mkcase c_vcap <<'EOF'
package cvcap

import (
	"fmt"

	"github.com/acme/ending/V"
)

func F() { fmt.Println(vcap.X) }
EOF
mkcase c_vonly <<'EOF'
package cvonly

import (
	"fmt"

	"github.com/acme/ending/v"
)

func F() { fmt.Println(vonly.X) }
EOF
mkcase c_misc <<'EOF'
package cmisc

import (
	"fmt"

	"github.com/acme/ending/v02"
	"github.com/acme/ending/v2v"
	"github.com/acme/ending/v9x"
	"github.com/acme/ending/vv2"
	"github.com/acme/ending/vx"
)

func F() { fmt.Println(v02pkg.X, v2vpkg.X, v9x.X, vv2pkg.X, vxpkg.X) }
EOF
./run2.sh c_vcap -set-alias
./run2.sh c_vonly -set-alias
./run2.sh c_misc -set-alias

cd /tmp/probe/alias &&
mkdir -p local/ending/foo local/ending/v9
printf 'package barname\n\nvar X = 1\n' > local/ending/foo/x.go
printf 'package v9\n\nvar X = 1\n' > local/ending/v9/x.go
mkcase() { d=$1; mkdir -p "cases/$d"; cat > "cases/$d/$d.go"; }
mkcase c_nonver_mismatch <<'EOF'
