	"fmt"

	"github.com/acme/ending/foo"
)

func F() { fmt.Println(barname.X) }
EOF
mkcase c_ver_match <<'EOF'
package cvermatch

import (
	"fmt"

	"github.com/acme/ending/v9"
)

